&lt;div class=&quot;presentation navmenudroite&quot;&gt;
&lt;h2 class=&quot;separator&quot;&gt;Les arch&#233;types de magus&lt;a class=&quot;headeranchor&quot; id=&quot;Les_arch&#233;types_de_magus_0&quot; href=&quot;#Les_arch&#233;types_de_magus_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;&amp;nbsp;Retour &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Magus.html&quot; title=&quot;Le magus&quot;&gt;classe&lt;/a&gt;.
&lt;ul style=&quot;margin-top:2px&quot;&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Archer-Occulte-(Magus).html&quot; title=&quot;Archer occulte&quot;&gt;Archer occulte&lt;/a&gt; (HOTS)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chevalier-&#201;l&#233;mentaire-(Magus).html&quot; title=&quot;Chevalier &#233;l&#233;mentaire (magus)&quot;&gt;Chevalier &#233;l&#233;mentaire&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Suli-(Race).html&quot; title=&quot;Les sulis&quot;&gt;Suli&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Danse-Sort-(Magus).html&quot; title=&quot;Danse-sort&quot;&gt;Danse-sort&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Elfe.html&quot; title=&quot;Les elfes&quot;&gt;Elfe&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;fenseur-De-La-Tour-(Magus).html&quot; title=&quot;D&#233;fenseur de la tour&quot;&gt;D&#233;fenseur de la tour&lt;/a&gt; (MMI)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;corcheur-Fi&#233;lon-(Magus).html&quot; title=&quot;&#201;corcheur fi&#233;lon&quot;&gt;&#201;corcheur fi&#233;lon&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Tieffelin-(Race).html&quot; title=&quot;Les tieffelins&quot;&gt;Tieffelin&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;sot&#233;riste-(Magus).html&quot; title=&quot;&#201;sot&#233;riste&quot;&gt;&#201;sot&#233;riste&lt;/a&gt; (AO)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Forge&#226;me-(Magus).html&quot; title=&quot;Forge&#226;me&quot;&gt;Forge&#226;me&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Kensai-(Magus).html&quot; title=&quot;Kensai&quot;&gt;Kensai&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Lameli&#233;-(Magus).html&quot; title=&quot;Lameli&#233;&quot;&gt;Lameli&#233;&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Lamesprit-(Magus).html&quot; title=&quot;Lamesprit&quot;&gt;Lamesprit&lt;/a&gt; (AO)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Lamesort-(Magus).html&quot; title=&quot;Lamesort&quot;&gt;Lamesort&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Lanceur-De-Mal&#233;fices-(Magus).html&quot; title=&quot;Lanceur de mal&#233;fices&quot;&gt;Lanceur de mal&#233;fices&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Mage-De-Bataille-Blind&#233;-(Magus).html&quot; title=&quot;Mage de bataille blind&#233;&quot;&gt;Mage de bataille blind&#233;&lt;/a&gt; (&lt;i&gt;AMH&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Myrmidarque-(Magus).html&quot; title=&quot;Myrmidarque&quot;&gt;Myrmidarque&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Rejeton-&#201;trange-(Magus).html&quot; title=&quot;Rejeton &#233;trange&quot;&gt;Rejeton &#233;trange&lt;/a&gt; (MCA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Skirnir-(Magus).html&quot; title=&quot;Skirnir&quot;&gt;Skirnir&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sp&#233;cialiste-Du-B&#226;ton-(Magus).html&quot; title=&quot;Sp&#233;cialiste du b&#226;ton&quot;&gt;Sp&#233;cialiste du b&#226;ton&lt;/a&gt; (AM)&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.LArt de la guerre (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Combat/Art de la Guerre&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoUC.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;i&gt;Le skirnir, que l’on appelle parfois vierge du bouclier ou vassal du bouclier, transmet ses pouvoirs &#224; son bouclier.&lt;/i&gt;&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Incantation r&#233;duite&lt;a class=&quot;headeranchor&quot; id=&quot;Incantation_r&#233;duite_0&quot; href=&quot;#Incantation_r&#233;duite_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Le skirnir lance un sort de moins de chaque niveau de sort que les &lt;a class=&quot;pagelink&quot; href=&quot;Magus.html&quot; title=&quot;Le magus&quot;&gt;magi&lt;/a&gt; ordinaires. Si ce changement fait passer son nombre de sorts &#224; 0, il peut lancer des sorts de ce niveau uniquement si son &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Intelligence.html&quot; title=&quot;L&amp;#39;Intelligence&quot;&gt;Intelligence&lt;/a&gt; lui accorde des sorts suppl&#233;mentaires pour ce niveau.&lt;br /&gt;&lt;br /&gt;
&lt;h3 class=&quot;separator&quot;&gt;Pacte magique (Sur)&lt;a class=&quot;headeranchor&quot; id=&quot;Pacte_magique_Sur_1&quot; href=&quot;#Pacte_magique_Sur_1&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Niveau.html&quot; title=&quot;niveau&quot;&gt;niveau&lt;/a&gt; 1, le skirnir gagne un bouclier (mais pas un pavois) comme &lt;a class=&quot;pagelink&quot; href=&quot;Magicien.html#PACTEMAGIQUE&quot; title=&quot;Le magicien&quot;&gt;objet f&#233;tiche&lt;/a&gt;. Ce pouvoir fonctionne comme celui de &lt;a class=&quot;pagelink&quot; href=&quot;Magicien.html&quot; title=&quot;Le magicien&quot;&gt;magicien&lt;/a&gt; mais le magus se lie forc&#233;ment &#224; un bouclier, jamais &#224; un autre objet ni &#224; un familier.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;R&#233;serve magique&lt;a class=&quot;headeranchor&quot; id=&quot;R&#233;serve_magique_2&quot; href=&quot;#R&#233;serve_magique_2&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 1, le skirnir peut d&#233;penser 1 point de sa &lt;a class=&quot;pagelink&quot; href=&quot;Magus#Reservemagique.html&quot; title=&quot;r&#233;serve magique&quot;&gt;r&#233;serve magique&lt;/a&gt; pour donner un bonus d’alt&#233;ration &#224; une arme, comme d’habitude, mais aussi &#224; son bouclier. Il paye le prix de chacun s&#233;par&#233;ment. &#192; partir du niveau 5, il peut aussi ajouter les propri&#233;t&#233;s magiques suivantes &#224; son bouclier : &lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Anim&#233;e.html&quot; title=&quot;anim&#233;e (propri&#233;t&#233;)&quot;&gt;anim&#233;&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Anti-Projectiles.html&quot; title=&quot;anti-projectiles (propri&#233;t&#233;)&quot;&gt;anti-projectiles&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Attaque.html&quot; title=&quot;attaque (propri&#233;t&#233;)&quot;&gt;d’attaque&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#Aveuglante.html&quot; title=&quot;aveuglante (propri&#233;t&#233;)&quot;&gt;aveuglant&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#D&#233;fense-(L&#233;g&#232;re).html&quot; title=&quot;d&#233;fense l&#233;g&#232;re (propri&#233;t&#233;)&quot;&gt;de d&#233;fense&lt;/a&gt; (n’importe), &lt;a class=&quot;pagelink&quot; href=&quot;Armures-Magiques#Interceptiondeprojectiles.html&quot; title=&quot;Interception de projectiles&quot;&gt;interception de projectiles&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#R&#233;fl&#233;chissante.html&quot; title=&quot;r&#233;fl&#233;chissante (propri&#233;t&#233;)&quot;&gt;r&#233;fl&#233;chissant&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#R&#233;sistance-&#192;-La-Magie-(13).html&quot; title=&quot;r&#233;sistance &#224; la magie 13 (propri&#233;t&#233;)&quot;&gt;r&#233;sistance &#224; la magie&lt;/a&gt; (n’importe).&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Bouclier ensorcel&#233; (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Bouclier_ensorcel&#233;_Ext_3&quot; href=&quot;#Bouclier_ensorcel&#233;_Ext_3&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 1, le skirnir apprend &#224; manier tous les types de bouclier, y compris les &lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Armures#Pavois.html&quot; title=&quot;pavois&quot;&gt;pavois&lt;/a&gt;, et ne souffre pas de risques d’&#233;chec des sorts profanes quand il lance un sort de magus alors qu’il manie un bouclier. Il consid&#232;re ses niveaux de &lt;a class=&quot;pagelink&quot; href=&quot;Magus.html&quot; title=&quot;Le magus&quot;&gt;magus&lt;/a&gt; comme des niveaux de &lt;a class=&quot;pagelink&quot; href=&quot;Guerrier.html&quot; title=&quot;Le guerrier&quot;&gt;guerrier&lt;/a&gt; quand il s’agit de remplir les conditions requises par un don en rapport avec les boucliers. Ce pouvoir remplace &lt;a class=&quot;pagelink&quot; href=&quot;Magus.html#COMBATMAGIQUE&quot; title=&quot;Le magus&quot;&gt;combat magique&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Frappe magique (Sur)&lt;a class=&quot;headeranchor&quot; id=&quot;Frappe_magique_Sur_4&quot; href=&quot;#Frappe_magique_Sur_4&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 1, le skirnir peut utiliser &lt;a class=&quot;pagelink&quot; href=&quot;Magus.html#FRAPPEMAGIQUE&quot; title=&quot;Le magus&quot;&gt;ce pouvoir&lt;/a&gt; avec une arme ou un bouclier.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;R&#233;serve magique (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;R&#233;serve_magique_Ext_5&quot; href=&quot;#R&#233;serve_magique_Ext_5&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 4, le skirnir peut, par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Libre.html&quot; title=&quot;Action libre&quot;&gt;action libre&lt;/a&gt;, d&#233;penser 1 point de sa &lt;a class=&quot;pagelink&quot; href=&quot;Magus#Reservemagique.html&quot; title=&quot;r&#233;serve magique&quot;&gt;r&#233;serve magique&lt;/a&gt; pour ajouter le bonus &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Ca.html&quot; title=&quot;CA&quot;&gt;CA&lt;/a&gt; de son bouclier &#224; ses tests de &lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Concentration.html&quot; title=&quot;Concentration&quot;&gt;Concentration&lt;/a&gt; sur la d&#233;fensive (sans compter les bonus d’alt&#233;ration). Il peut aussi faire une &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Attaquesdecontact.html&quot; title=&quot;attaque de contact&quot;&gt;attaque de contact&lt;/a&gt; ou un coup de bouclier pour appliquer des pouvoirs de r&#233;serve de coups. Ce pouvoir remplace &lt;a class=&quot;pagelink&quot; href=&quot;Magus.html#SOUVENIRMAGIQUE&quot; title=&quot;Le magus&quot;&gt;souvenir magique&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Bouclier de sorts (Sur)&lt;a class=&quot;headeranchor&quot; id=&quot;Bouclier_de_sorts_Sur_6&quot; href=&quot;#Bouclier_de_sorts_Sur_6&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 7, le skirnir peut, par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Simple.html&quot; title=&quot;Action simple&quot;&gt;action simple&lt;/a&gt;, stocker un sort de magus dans son bouclier s’il d&#233;pense 1 point de sa &lt;a class=&quot;pagelink&quot; href=&quot;Magus#Reservemagique.html&quot; title=&quot;r&#233;serve magique&quot;&gt;r&#233;serve magique&lt;/a&gt; par niveau de sort. Ceci fonctionne comme la propri&#233;t&#233; d’arme &lt;a class=&quot;unknownlink&quot; href=&quot;Stockage-De-Sort.html&quot; title=&quot;Pathfinder-RPG.stockage de sort&quot;&gt;stockeuse de sorts&lt;/a&gt; mais s’active uniquement si le skirnir r&#233;ussit un coup de bouclier et ne se limite pas &#224; des sorts de niveau 3 ou moins. Ce pouvoir remplace &lt;a class=&quot;pagelink&quot; href=&quot;Magus.html#RESERVEDECONNAISSANCES&quot; title=&quot;Le magus&quot;&gt;r&#233;serve de connaissances&lt;/a&gt;.
&lt;h3 class=&quot;separator&quot;&gt;Combat magique au bouclier (Sur)&lt;a class=&quot;headeranchor&quot; id=&quot;Combat_magique_au_bouclier_Sur_7&quot; href=&quot;#Combat_magique_au_bouclier_Sur_7&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 8 le skirnir gagne le pouvoir &lt;a class=&quot;pagelink&quot; href=&quot;Magus.html#COMBATMAGIQUE&quot; title=&quot;Le magus&quot;&gt;combat magique&lt;/a&gt;, mais seulement quand il manie son bouclier f&#233;tiche. Il peut renoncer &#224; son bonus de bouclier &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Ca.html&quot; title=&quot;CA&quot;&gt;CA&lt;/a&gt; jusqu’au d&#233;but de son prochain tour pour ex&#233;cuter les composantes somatiques d’un sort de magus. Si le bouclier est une targe, il conserve le bonus &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Ca.html&quot; title=&quot;CA&quot;&gt;CA&lt;/a&gt;. Au niveau 14, il gagne &lt;a class=&quot;pagelink&quot; href=&quot;Magus.html#SCIENCEDUCOMBATMAGIQUE&quot; title=&quot;Le magus&quot;&gt;science du combat magique&lt;/a&gt;. Au niveau 19, il conserve son bonus de bouclier &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Ca.html&quot; title=&quot;CA&quot;&gt;CA&lt;/a&gt; quel que soit le type de bouclier qu’il utilise. Ce pouvoir remplace &lt;a class=&quot;pagelink&quot; href=&quot;Magus.html#SCIENCEDUCOMBATMAGIQUE&quot; title=&quot;Le magus&quot;&gt;science du combat magique&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Magus.html#COMBATMAGIQUESUPERIEUR&quot; title=&quot;Le magus&quot;&gt;combat magique sup&#233;rieur&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;Magus.html#ACCESAUXSORTSSUPERIEUR&quot; title=&quot;Le magus&quot;&gt;acc&#232;s aux sorts sup&#233;rieur&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Bouclier de sorts sup&#233;rieur (Sur)&lt;a class=&quot;headeranchor&quot; id=&quot;Bouclier_de_sorts_sup&#233;rieur_Sur_8&quot; href=&quot;#Bouclier_de_sorts_sup&#233;rieur_Sur_8&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 16, le skirnir peut activer un sort stock&#233; par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Immediate.html&quot; title=&quot;Action imm&#233;diate&quot;&gt;action imm&#233;diate&lt;/a&gt;, d&#232;s qu’il est touch&#233; en combat. Le sort peut l’affecter lui ou agir sur la cr&#233;ature qui l’a frapp&#233;. Ce pouvoir remplace &lt;a class=&quot;pagelink&quot; href=&quot;Magus.html#RIPOSTER&quot; title=&quot;Le magus&quot;&gt;riposter&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Arcanes de magus conseill&#233;s&lt;a class=&quot;headeranchor&quot; id=&quot;Arcanes_de_magus_conseill&#233;s_9&quot; href=&quot;#Arcanes_de_magus_conseill&#233;s_9&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Voici les arcanes qui viennent compl&#233;ter le skirnir : &lt;a class=&quot;pagelink&quot; href=&quot;Arcanes#Defendreavecprescience.html&quot; title=&quot;d&#233;fendre avec prescience&quot;&gt;d&#233;fendre avec prescience&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Arcanes#Fortificationarcanique.html&quot; title=&quot;fortification arcanique&quot;&gt;fortification arcanique&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Arcanes#Fortificationarcaniquesuperieure.html&quot; title=&quot;fortification arcanique sup&#233;rieure&quot;&gt;fortification arcanique sup&#233;rieure&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Arcanes#Lamelongueduree.html&quot; title=&quot;lame longue dur&#233;e&quot;&gt;lame longue dur&#233;e&lt;/a&gt; (utilisable sur une arme ou un bouclier), &lt;a class=&quot;pagelink&quot; href=&quot;Arcanes#Renvoi.html&quot; title=&quot;renvoi&quot;&gt;renvoi&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Arcanes#Reservedecoups.html&quot; title=&quot;r&#233;serve de coups&quot;&gt;r&#233;serve de coups&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Arcanes#Reservedecoupsaricochet.html&quot; title=&quot;r&#233;serve de coups &#224; ricochet (arcane)&quot;&gt;&#224; ricochet&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Arcanes#Reservedecoupspersistante.html&quot; title=&quot;r&#233;serve de coups persistante&quot;&gt;persistante&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Arcanes#Reservedecoupstonitruante.html&quot; title=&quot;r&#233;serve de coups tonitruante&quot;&gt;tonitruante&lt;/a&gt;).
